const V297_SIM_GEO_MAP=new Map(V297_SIM_GEO_SUMMARY.map(r=>[norm(r.n),r]));
function v297FindSimSummary(point){
  const aliases=[point?.name,...(point?.somAliases||[]),...(point?.aliases||[])].filter(Boolean);
  for(const alias of aliases){const row=V297_SIM_GEO_MAP.get(norm(alias));if(row)return row;}
  return null;
}
function v297Fmt(v,d=1,suffix=''){const n=Number(v);return Number.isFinite(n)?n.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d})+suffix:'—';}
function v297SimuladoCard(point){
  const r=v297FindSimSummary(point);
  if(!r)return `<div class="geo-result-block" data-v297-sim><div class="geo-result-title"><strong>Simulado 2026</strong><span>resultados da escola</span></div><div class="geo-empty">Esta unidade não possui resultado escolar do Simulado 2026 nos anos carregados.</div></div>`;
  const row2=(Number.isFinite(Number(r['2LPa']))||Number.isFinite(Number(r['2MTa'])))?`<div class="geo-mini-row"><div><strong>2º ano</strong><span>LP: % Alfabetizados · MT: % Adequado + Avançado</span></div><div class="geo-mini-metrics" style="min-width:176px"><span class="geo-mini-value">LP ${v297Fmt(r['2LPa'],1,'%')} alfabetizados</span><span class="geo-mini-median">MT ${v297Fmt(r['2MTa'],1,'%')} Adequado + Avançado</span></div></div>`:'';
  const row4=Number.isFinite(Number(r['4np']))?`<div class="geo-mini-row"><div><strong>4º ano</strong><span>Nota Padronizada = média simples LP + MT</span></div><div class="geo-mini-metrics" style="min-width:160px"><span class="geo-mini-value">${v297Fmt(r['4np'],1)}</span><span class="geo-mini-median">LP ${v297Fmt(r['4LP'],1)} · MT ${v297Fmt(r['4MT'],1)}</span></div></div>`:'';
  const row8=Number.isFinite(Number(r['8np']))?`<div class="geo-mini-row"><div><strong>8º ano</strong><span>Nota Padronizada = média simples LP + MT</span></div><div class="geo-mini-metrics" style="min-width:160px"><span class="geo-mini-value">${v297Fmt(r['8np'],1)}</span><span class="geo-mini-median">LP ${v297Fmt(r['8LP'],1)} · MT ${v297Fmt(r['8MT'],1)}</span></div></div>`:'';
  return `<div class="geo-result-block" data-v297-sim><div class="geo-result-title"><strong>Simulado 2026</strong><span>resultados da escola</span></div><div class="geo-mini-list">${row2+row4+row8||'<div class="geo-empty">Sem resultados disponíveis.</div>'}</div></div>`;
}

// Injeta o Simulado no mesmo card lateral já usado pelo mapa.
const __v297GeoOpenDetail=geoOpenDetail;
geoOpenDetail=function(point){
  __v297GeoOpenDetail(point);
  const detail=document.getElementById('geoDetail');
  const body=detail?.querySelector('.geo-detail-body');
  if(!body)return;
  body.querySelector('[data-v297-sim]')?.remove();
  const agent=body.querySelector('.geo-agent');
  if(agent)agent.insertAdjacentHTML('afterend',v297SimuladoCard(point));
  else body.insertAdjacentHTML('afterbegin',v297SimuladoCard(point));
};

// O container capturava o pointer no pointerdown. Assim o click final podia ser retargeted
// para #geoMap e nunca chegar ao canvas. Fazemos o hit-test no pointerup do próprio mapa.
function v297BindCanvasSelection(){
  const map=document.getElementById('geoMap');
  if(!map||map.dataset.v297CanvasSelection==='1')return;
  map.dataset.v297CanvasSelection='1';
  map.addEventListener('pointerup',event=>{
    if(Date.now()<(GEO_STATE.suppressClickUntil||0))return;
    if(GEO_STATE.dragMoved)return;
    if(event.pointerType==='touch'&&event.isPrimary===false)return;
    const hit=geoCanvasHitAt(event.clientX,event.clientY);
    if(!hit)return;
    GEO_STATE.dragging=false;
    GEO_STATE.suppressClickUntil=Date.now()+320;
    event.preventDefault();event.stopPropagation();
    geoOpenDetail(hit.point);
  },true);
}
const __v297GeoInitStage=geoInitStage;
geoInitStage=function(){const r=__v297GeoInitStage.apply(this,arguments);v297BindCanvasSelection();return r;};
if(document.getElementById('geoMap'))v297BindCanvasSelection();

// Texto abreviado continua cabendo; tooltip/título preserva a expressão inteira.
const __v297GeoUpdateLegend=geoUpdateLegend;
geoUpdateLegend=function(){
  const r=__v297GeoUpdateLegend.apply(this,arguments);
  const labels=geoLegendLabels();
  document.querySelectorAll('[data-geo-legend]').forEach(el=>{
    const full=labels[el.dataset.geoLegend]||'';
    if(full){el.dataset.fullLabel=full;el.title=full;}else{delete el.dataset.fullLabel;el.removeAttribute('title');}
  });
  return r;
};
